insert into public.npt_catalog_sources(key,name,url,license_notes,coverage_notes) values
('nps','National Park Service Data API','https://www.nps.gov/subjects/developer/index.htm','Retain image-specific rights and credits.','NPS API snapshot; not exhaustive national campground coverage.'),
('padus','USGS PAD-US 4.1','https://doi.org/10.5066/P96WBCHS','USGS public data.','State park inventory; centroids are not entrances. Agency verification and campground enrichment required.'),
('parks_canada','Parks Canada','https://parks.canada.ca/pn-np/ab/banff','Image-specific rights require review.','Initial Banff official records.'),
('koa','KOA (Kampgrounds of America) official campground directory','https://koa.com/campgrounds/','Retain source attribution; respect KOA site terms.','Official discovery directory registered. Current database has only a small sample; national campground and campsite detail refresh is pending.'),
('els','Equity LifeStyle Properties (ELS) RV portfolio','https://www.equitylifestyleproperties.com/our-portfolio/rv-portfolio/','Retain source attribution; respect ELS site terms.','Official RV portfolio registered. Individual campground and site-level hookups, RV limits, fees, and booking data require source-page verification. Cross-listed properties must be deduplicated.'),
('adventure_bound','Adventure Bound Camping Resorts official directory','https://www.abcamping.com/','Retain source attribution; respect Adventure Bound site terms.','Official resort directory registered. Individual campground and campsite details require source-page verification.'),
('sun_outdoors','Sun Outdoors official location directory','https://www.sunoutdoors.com/locations','Retain source attribution; respect Sun Outdoors site terms.','Official location directory registered. Existing imported records are an initial sample; nationwide campground and campsite detail refresh is pending.'),
('thousand_trails_encore','Thousand Trails / Encore official resort directory','https://thousandtrails.com/memberships','Retain source attribution; respect ELS/Thousand Trails site terms.','Official membership resort directory registered. Cross-listed properties may also appear in ELS portfolio; deduplicate before import. Site-level details require verification.'),
('jellystone','Yogi Bear’s Jellystone Park Camp-Resorts official directory','https://www.campjellystone.com/locations','Retain source attribution; respect Jellystone site terms.','Official location directory registered. Individual campground and campsite details require source-page verification.'),
('blue_water','Blue Water Development official portfolio','https://bwdc.com/real-estate-development-portfolio/','Retain source attribution; respect Blue Water site terms.','Official portfolio registered. Managed properties may be cross-listed under KOA, Jellystone, Sun Outdoors, or other brands; deduplicate physical properties and retain all verified operator/brand relationships.'),
('spacious_skies','Spacious Skies Campgrounds official directory','https://spaciousskiescampgrounds.com/our-campgrounds/','Retain source attribution; respect Spacious Skies site terms.','Official location directory registered. Individual campground and campsite details require source-page verification.')
